/*
 * Firefly base styles — design tokens + motion foundation.
 * Installed by `firefly-base` as app/firefly.css. Import it right after Tailwind in app/globals.css:
 *
 *   @import "tailwindcss";
 *   @import "./firefly.css";
 *
 * Fonts: load Inter (--font-inter) and IBM Plex Mono (--font-plex-mono) with next/font in app/layout.tsx.
 * When a client's Figma has its own variables, change the VALUES here (keep the names) so every
 * installed component picks up the client palette.
 */
@theme {
  /* Text */
  --color-text-primary: #0a0a0a;
  --color-text-secondary: #515258;
  --color-text-tertiary: #696969;
  --color-text-quaternary: #878787;
  --color-text-placeholder: #9e9e9e;
  /* Grey half of two-tone headlines and muted copy. 3.0:1 on the page background (WCAG AA large text). */
  --color-text-muted: #919191;
  --color-text-nav: #6b6b6b;
  --color-text-inverse: #fafafa;
  --color-text-on-dark: #f5f7fa;

  /* Icons */
  --color-icon-primary: #0a0a0a;
  --color-icon-secondary: #636363;
  --color-icon-tertiary: #878787;
  --color-icon-quaternary: #b2b2b2;

  /* Surfaces */
  --color-surface-page: #fdfcfc;
  --color-surface-primary: #ffffff;
  --color-surface-secondary: #f8f8fb;
  --color-surface-muted: #f5f5f5;
  --color-surface-card-light: #f2f2f2;
  --color-surface-card-dark: #1b1b1b;
  --color-surface-inverse: #0a0a0a;
  --color-surface-dark: #0f1115;

  /* Borders */
  --color-border-04: #0000000a;
  --color-border-06: #0000000f;
  --color-border-10: #0000001a;
  --color-border-16: #00000029;
  --color-border-24: #0000003d;
  --color-border-light: #e8e8e8;
  --color-border-dark: #2a2a2a;
  --color-border-on-dark: #2a2f3a;
  --color-border-interactive: #3f51f4;

  /* Buttons */
  --color-button-primary: #0a0a0a;
  --color-button-content-primary: #ffffff;
  --color-button-secondary: #0000000f;
  --color-button-content-secondary: #0a0a0a;

  /* Status (tags, dots) */
  --color-status-positive: #166534;
  --color-status-positive-bg: #f0fdf4;
  --color-status-negative: #b91c1c;
  --color-status-negative-bg: #fff5f5;
  --color-status-warning: #b94020;
  --color-status-warning-bg: #fff1ec;

  /* Radii (named to avoid clashing with Tailwind's rounded-s / rounded-l side utilities) */
  --radius-chip: 6px;
  --radius-tile: 8px;
  --radius-frame: 12px;
  --radius-card: 14px;
  --radius-pill: 9999px;

  /* Shadows */
  --shadow-card-drop: 0 30px 70px 0 #0000000a;
  --shadow-soft: 0 16px 40px 0 #0000000f;

  /* Type */
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: var(--font-plex-mono), ui-monospace, "SF Mono", Menlo, monospace;

  /* Motion */
  --ease-out-soft: cubic-bezier(0.22, 1, 0.36, 1);
}

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    scroll-padding-top: 80px;
  }
  @media (prefers-reduced-motion: no-preference) {
    html {
      scroll-behavior: smooth;
    }
  }
  body {
    background: var(--color-surface-page);
    color: var(--color-text-primary);
    font-family: var(--font-sans);
    overflow-x: clip;
  }
  :focus-visible {
    outline: 2px solid var(--color-border-interactive);
    outline-offset: 3px;
    border-radius: 4px;
  }
}

/*
 * Scroll reveals.
 * Content is fully visible by default (SSR, no JS, crawlers, reduced motion). Only when the
 * <MotionScript> head script adds `.motion-ok` to <html> are [data-reveal] elements hidden until
 * <Reveal> marks them `data-in`. Only transform + opacity animate.
 */
.motion-ok [data-reveal] {
  opacity: 0;
  transform: translate3d(0, var(--reveal-y, 20px), 0);
  transition:
    opacity 0.8s var(--ease-out-soft),
    transform 0.9s var(--ease-out-soft);
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}
.motion-ok [data-reveal][data-in] {
  opacity: 1;
  transform: none;
}

/* Body of an accordion / step list fading in when its item opens */
@keyframes feature-in {
  from {
    opacity: 0;
    transform: translate3d(0, 6px, 0);
  }
}

/* Marquees: the track holds two identical copies and moves by half its width */
@keyframes marquee-left {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(-50%, 0, 0);
  }
}
@keyframes marquee-right {
  from {
    transform: translate3d(-50%, 0, 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

/**
 * Put <MotionScript /> inside <head> in app/layout.tsx.
 *
 * Enables reveal animations only when JS runs and the user allows motion: adds `motion-ok`
 * to <html>. Failsafe: if the app never hydrates (no <Reveal> mounted), everything is
 * revealed after 3s so content is never stuck hidden.
 */
export const motionScript = `(function(){try{var d=document.documentElement;if(!matchMedia('(prefers-reduced-motion: reduce)').matches){d.classList.add('motion-ok');setTimeout(function(){if(!('revealReady' in d.dataset))d.classList.remove('motion-ok')},3000)}}catch(e){}})();`;

export function MotionScript() {
  return <script dangerouslySetInnerHTML={{ __html: motionScript }} />;
}

"use client";

import { inView } from "motion";
import {
  useEffect,
  useRef,
  type ComponentPropsWithoutRef,
  type ElementType,
  type ReactNode,
} from "react";

/**
 * Scroll-triggered reveal (fade + slight rise), fired once at ~20% in view.
 *
 * <Reveal> is a container. It reveals every descendant marked with `data-reveal`
 * (use <RevealItem> or spread `reveal` from ./reveal-attr), staggering them in DOM order.
 * Spread `reveal` on the <Reveal> itself to animate it too.
 *
 * Content is visible without JS / with reduced motion: the hidden state is only applied
 * under `html.motion-ok` (see firefly.css + <MotionScript> in the layout head).
 */
type RevealProps<T extends ElementType> = {
  as?: T;
  children: ReactNode;
  /** ms between staggered children (default 90) */
  stagger?: number;
  /** ms before the first child */
  delay?: number;
  /** fraction of the element that must be visible (default 0.2) */
  amount?: number;
} & Omit<ComponentPropsWithoutRef<T>, "as" | "children">;

export function Reveal<T extends ElementType = "div">({
  as,
  children,
  stagger = 90,
  delay = 0,
  amount = 0.2,
  ...rest
}: RevealProps<T>) {
  const Tag = (as ?? "div") as ElementType;
  const ref = useRef<HTMLElement>(null);

  useEffect(() => {
    const root = ref.current;
    if (!root) return;
    document.documentElement.dataset.revealReady = "";

    const items = Array.from(root.querySelectorAll<HTMLElement>("[data-reveal]"));
    const targets = root.hasAttribute("data-reveal") ? [root, ...items] : items;
    targets.forEach((el, i) => {
      el.style.setProperty("--reveal-delay", `${delay + i * stagger}ms`);
    });

    return inView(
      root,
      () => {
        targets.forEach((el) => el.setAttribute("data-in", ""));
      },
      { amount }
    );
  }, [amount, delay, stagger]);

  return (
    <Tag ref={ref} {...rest}>
      {children}
    </Tag>
  );
}

export function RevealItem<T extends ElementType = "div">({
  as,
  children,
  ...rest
}: { as?: T; children?: ReactNode } & Omit<ComponentPropsWithoutRef<T>, "as" | "children">) {
  const Tag = (as ?? "div") as ElementType;
  return (
    <Tag data-reveal="" {...rest}>
      {children}
    </Tag>
  );
}

/**
 * Spread onto any element inside <Reveal> to make it a staggered reveal child.
 * Lives outside the "use client" reveal module so Server Components get the real object
 * (values exported from a client module become client references and the animation never runs).
 */
export const reveal = { "data-reveal": "" } as const;

"use client";

import { motion, useReducedMotion, useScroll, useTransform } from "motion/react";
import { useEffect, useRef, useState, type ReactNode } from "react";

/**
 * Subtle vertical parallax for large visuals (transform only).
 *
 * mode "through" (default): drifts from +distance to -distance while the element crosses
 *   the viewport. For visuals further down the page (≈30px).
 * mode "exit": starts at 0 (renders exactly in place on load) and drifts down by `distance`
 *   as the element scrolls out. For the hero visual (≈60px).
 *
 * Disabled under prefers-reduced-motion.
 */
export function Parallax({
  children,
  distance = 30,
  mode = "through",
  className = "",
}: {
  children: ReactNode;
  distance?: number;
  mode?: "through" | "exit";
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const reduce = useReducedMotion();
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: mode === "exit" ? ["start start", "end start"] : ["start end", "end start"],
  });
  const y = useTransform(scrollYProgress, (p) =>
    mode === "exit" ? p * distance : distance - p * 2 * distance
  );
  // The server can't know the motion preference, so the first client render matches the
  // server and the parallax is switched off right after hydration if needed.
  const [enabled, setEnabled] = useState(true);
  useEffect(() => setEnabled(!reduce), [reduce]);

  return (
    <div ref={ref} className={className}>
      <motion.div style={{ y: enabled ? y : 0 }} className="h-full w-full will-change-transform">
        {children}
      </motion.div>
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Sets `--art-scale` on its parent element: max(1, parentWidth / designWidth).
 * Lets a decorative composition drawn at a fixed design width (1440px) grow to cover
 * wider screens via `scale-[var(--art-scale,1)]` instead of leaving empty bands.
 */
export function ArtScale({ designWidth = 1440 }: { designWidth?: number }) {
  const ref = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const parent = ref.current?.parentElement;
    if (!parent) return;
    const update = () =>
      parent.style.setProperty("--art-scale", String(Math.max(1, parent.clientWidth / designWidth)));
    update();
    const ro = new ResizeObserver(update);
    ro.observe(parent);
    return () => ro.disconnect();
  }, [designWidth]);

  return <span ref={ref} hidden />;
}

import Link from "next/link";
import type { ComponentPropsWithoutRef } from "react";

export type ButtonVariant = "dark" | "ghost" | "light";
export type ButtonSize = "sm" | "md";

const base =
  "inline-flex cursor-pointer items-center justify-center whitespace-nowrap rounded-pill font-medium leading-none " +
  "transition-[translate,scale,opacity] duration-200 ease-out hover:-translate-y-px active:translate-y-0 active:scale-[0.98] " +
  "motion-reduce:transition-none motion-reduce:hover:translate-y-0";

const variants: Record<ButtonVariant, string> = {
  /** Primary pill on light backgrounds */
  dark: "bg-button-primary text-button-content-primary hover:opacity-85",
  /** Secondary pill on light backgrounds */
  ghost: "border border-border-light bg-surface-primary text-text-primary hover:opacity-70",
  /** Primary pill on dark backgrounds */
  light: "bg-surface-primary text-text-primary hover:opacity-85",
};

// nav button 13px / 34px tall; hero button 14px / 43px tall
const sizes: Record<ButtonSize, string> = {
  sm: "h-[34px] px-4 text-[13px]",
  md: "h-[43px] px-5 text-[14px]",
};

type Common = { variant?: ButtonVariant; size?: ButtonSize; className?: string };
type AsLink = Common & Omit<ComponentPropsWithoutRef<typeof Link>, "className"> & { href: string };
type AsButton = Common & Omit<ComponentPropsWithoutRef<"button">, "className"> & { href?: undefined };

/** Pill button. Renders a Next <Link> when `href` is given, otherwise a native <button>. */
export function Button(props: AsLink | AsButton) {
  const { variant = "dark", size = "md", className = "", ...rest } = props;
  const classes = `${base} ${variants[variant]} ${sizes[size]} ${className}`;
  if (rest.href !== undefined) {
    return <Link className={classes} {...(rest as AsLink)} />;
  }
  const { type = "button", ...buttonProps } = rest as AsButton;
  return <button type={type} className={classes} {...buttonProps} />;
}

import { Button } from "@/components/ui/button";

export type CtaLink = { label: string; href: string };

/**
 * Hero call-to-action pair used on every page: a dark primary pill + a ghost secondary pill
 * (no arrow-only buttons). Pass `onDark` on dark sections.
 */
export function HeroCta({
  primary = { label: "Join waitlist", href: "#cta" },
  secondary = { label: "Book a demo", href: "#cta" },
  onDark = false,
  className = "",
}: {
  primary?: CtaLink;
  secondary?: CtaLink | null;
  onDark?: boolean;
  className?: string;
}) {
  return (
    <div className={`flex flex-wrap items-center gap-2 ${className}`}>
      <Button href={primary.href} variant={onDark ? "light" : "dark"}>
        {primary.label}
      </Button>
      {secondary ? (
        <Button
          href={secondary.href}
          variant="ghost"
          className={onDark ? "border-text-on-dark/25 bg-transparent text-text-on-dark" : ""}
        >
          {secondary.label}
        </Button>
      ) : null}
    </div>
  );
}

/**
 * Two-tone headline text: the first part in the primary colour, the second half in the
 * muted grey (house rule for every h1/h2). Renders inside the heading element you own:
 *
 *   <h2 className="..."><TwoTone text="Three weeks of diligence." muted="Or twelve minutes." /></h2>
 *
 * `stack` puts the muted part on its own line (display headlines).
 */
export function TwoTone({
  text,
  muted,
  stack = false,
  onDark = false,
}: {
  text: string;
  muted?: string;
  stack?: boolean;
  onDark?: boolean;
}) {
  if (!muted) return <>{text}</>;
  const mutedClass = onDark ? "text-text-on-dark/60" : "text-text-muted";
  return (
    <>
      <span className={stack ? "block" : undefined}>{text}</span>
      {stack ? null : " "}
      <span className={`${mutedClass} ${stack ? "block" : ""}`}>{muted}</span>
    </>
  );
}

import type { CSSProperties } from "react";

/**
 * Content-free stand-in for an image or product visual. Library components render it by
 * default; a site replaces it with a real `next/image` (or its own mockup) through props.
 *
 * Draws a soft hatched panel with a small mono label. Decorative (aria-hidden).
 */
export function Placeholder({
  label = "Visual",
  ratio,
  tone = "light",
  className = "",
  style,
}: {
  label?: string;
  /** CSS aspect-ratio, e.g. "16 / 10". Omit to fill the parent. */
  ratio?: string;
  tone?: "light" | "dark";
  className?: string;
  style?: CSSProperties;
}) {
  const tones = {
    light: "bg-surface-muted text-text-quaternary",
    dark: "bg-surface-card-dark text-text-on-dark/50",
  } as const;
  return (
    <div
      aria-hidden
      style={{ aspectRatio: ratio, ...style }}
      className={`relative flex h-full w-full items-center justify-center overflow-clip ${tones[tone]} ${className}`}
    >
      <div
        className="absolute inset-0 opacity-60 [background-image:repeating-linear-gradient(135deg,transparent_0_14px,color-mix(in_srgb,currentColor_12%,transparent)_14px_15px)]"
      />
      <span className="relative rounded-pill border border-current/20 px-2.5 py-1 font-mono text-[11px] uppercase tracking-[0.08em]">
        {label}
      </span>
    </div>
  );
}
